import threading
from ta_egate_cmd_parser.egate_connection import get_connection
from ta_egate_cmd_parser.egate_command_base import format_console_output


class EventDoesNotOccur(Exception):
    """
    Exception class
    """
    def __init__(self, regexp, timeout, output):
        """

        :param regexp:
        :param timeout:
        :param output:
        """
        self.regexp = regexp
        self.timeout = timeout
        self.output = output

    def __str__(self):
        self.err = "\nEvent: {}\n did not occur within timeout: {}\n egate output: {}"\
            .format(self.regexp,
                    self.timeout,
                    format_console_output(self.output))
        return self.err


class EventOccuredCallbackFailed(Exception):
    """
    Exception class
    """
    def __init__(self, regexp, timeout, callback_e):
        """

        :param regexp:
        :param timeout:
        :param callback_e:
        """
        self.regexp = regexp
        self.timeout = timeout
        self.callback_e = callback_e

    def __str__(self):
        self.err = "\nEvent: {}\n did occur within timeout: {}\n but callback failed with error: {}"\
            .format(self.regexp,
                    self.timeout,
                    self.callback_e)
        return self.err


class EgateWait4(object):
    """
    Class for handling threaded waiting for output with possiblity of automated callback invocaton on event detection.
    """
    def __init__(self, regexp, timeout, egate_id=0, callback=None, cyclic=False):
        """

        :param regexp:
        :param timeout:
        :param egate_id:
        :param callback:
        :param cyclic:
        """
        self.regexp = regexp
        self.timeout = timeout
        self.callback = callback
        self.cyclic = cyclic
        self.is_started = threading.Semaphore(0)
        self.is_running = threading.Event()
        self.thread = None
        self.connection = None
        self.callback_error = None
        self.status = None
        self.egate_output = None
        self._create_thread_waiting_for_egate_output(egate_id)

    def _create_thread_waiting_for_egate_output(self, egate_id):
        self.connection = get_connection(egate_id)
        self.is_running.set()
        self.thread = self._create_thread_instance()
        self.thread.start()
        self.is_started.acquire()

    def _create_thread_instance(self):
        return threading.Thread(target=self._thread_loop)

    def _thread_loop(self):
        self.is_started.release()
        while self.is_running.is_set():
            self.status, self.egate_output = self._get_status_and_output_from_connection()
            if self.status is True and self.callback is not None:
                try:
                    self.callback()
                except Exception as e:
                    self.callback_error = e
            if not self.cyclic:
                self.is_running.clear()
        self.connection.close()

    def _get_status_and_output_from_connection(self):
        status, out = self.connection.read_until_regexp(regexp=self.regexp, timeout=self.timeout)
        return status, out

    def wait_for_event(self):
        """
        Wait until thread that is waiting for specific event ends. The function is blocking.

        :return:
        """
        self.is_running.clear()
        self.thread.join()
        if not self.status:
            raise EventDoesNotOccur(self.regexp, self.timeout, self.egate_output)
        if self.callback_error is not None:
            raise EventOccuredCallbackFailed(self.regexp, self.timeout, self.callback_error)

    def destroy(self):
        """
        Destroys event, does not take care of its status or callback execution

        :return:
        """
        self.connection.close()
        self.is_running.clear()
        self.thread.join()


egate_connections = []


def create_event(regexp, timeout, callback=None, cyclic=False, egate_id=0):
    """
    Create single or cyclic event with/without callback function.

    :param regexp: regexp string
    :param timeout:
    :param callback:
    :param cyclic:
    :return:
    """
    global egate_connections
    instance = EgateWait4(regexp, timeout, egate_id, callback, cyclic)
    egate_connections.append(instance)
    return instance


def wait_for_event_finish(event):
    """
    Blocks until event with given timeout finishes

    :param event:
    :return:
    """
    # what if wait_for_event fails ? should event to be removed from connection earlier? will double event close produce error?
    event.wait_for_event()
    egate_connections.remove(event)


def destroy_event(event):
    """
    Blocks until event finishes but does not raise in case of failures

    :param event:
    :return:
    """
    global egate_connections
    event.destroy()
    egate_connections.remove(event)


def destroy_all_events():
    """
    Blocks until all events finish but does not raise in case of failures

    :return:
    """
    global egate_connections
    while len(egate_connections):
        destroy_event(egate_connections[0])
